begin;
lock table public.clinical_guidelines in share mode;
lock table public.guideline_versions in share row exclusive mode;
create temporary table population_batch on commit drop as
select * from jsonb_to_recordset($population$[{"id":"3f22251d-c5e6-4dfa-b52c-599b05e0bd4c","title":"Antenatal Care for Uncomplicated Pregnancy","original_version_id":"3f22251d-c5e6-4dfa-b52c-599b05e0bd4c","expected_hash":"3605057917534cfce84fef224426ae9b","source_url":"https://www.nice.org.uk/guidance/ng201/chapter/recommendations","source_title":"Antenatal care","issuer":"NICE","scope":"Pregnant women receiving routine antenatal care for an uncomplicated singleton pregnancy; this limited extraction covers booking, selected screening tests and routine ultrasound timing.","content":{"id":"3f22251d-c5e6-4dfa-b52c-599b05e0bd4c","title":"Antenatal Care for Uncomplicated Pregnancy","specialty":"Obstetrics","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b003","lastReviewed":"2026-10-10","pillar":"Safe Birth","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Pregnancy causes coordinated cardiovascular, renal, endocrine, and immune adaptations to support fetal growth. Antenatal care detects maternal/fetal risks, supports prevention, and provides timely response to emerging complications. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Pregnancy causes coordinated cardiovascular, renal, endocrine, and immune adaptations to support fetal growth. Antenatal care detects maternal/fetal risks, supports prevention, and provides timely response to emerging complications.","Clinical expression and progression vary with baseline risk, comorbidity, treatment exposure, and access to timely care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Antenatal Care for Uncomplicated Pregnancy, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Bleeding with pain or syncope","Severe headache, visual change, or upper abdominal pain later in pregnancy","Reduced fetal movement after the expected pattern is established","Fever, fluid loss, or preterm contractions"]},"differentials":[{"condition":"Ectopic pregnancy","distinguishingFeatures":"Pain/bleeding and uncertain location require urgent assessment."},{"condition":"Molar pregnancy","distinguishingFeatures":"Symptoms or ultrasound pattern may suggest abnormal gestation."},{"condition":"High-risk pregnancy","distinguishingFeatures":"Comorbidity or prior complication changes care setting and schedule."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Confirm pregnancy dating and baseline maternal health; offer locally recommended blood group, infection, anaemia, and fetal screening.","modalityTarget":"Confirm pregnancy dating and baseline maternal health; offer locally recommended blood group, infection, anaemia, and fetal screening. — Antenatal Care for Uncomplicated Pregnancy","targetCondition":"Antenatal Care for Uncomplicated Pregnancy","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"specializedAdjunctive","testName":"Use current Saudi antenatal schedule and informed consent; arrange ultrasound and referrals based on gestation and risk.","modalityTarget":"Use current Saudi antenatal schedule and informed consent; arrange ultrasound and referrals based on gestation and risk. — Cause, complication, or risk relevant to Antenatal Care for Uncomplicated Pregnancy","targetCondition":"Cause, complication, or risk relevant to Antenatal Care for Uncomplicated Pregnancy","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Antenatal Care for Uncomplicated Pregnancy","targetCondition":"Important alternative to Antenatal Care for Uncomplicated Pregnancy","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Pregnant women receiving routine antenatal care for an uncomplicated singleton pregnancy; this limited extraction covers booking, selected screening tests and routine ultrasound timing. This international source must be reconciled with current Saudi maternity pathways, laboratory panels, haemoglobinopathy and infectious-disease screening programmes, vaccination policy, rhesus prophylaxis, diabetes guidance and referral thresholds. It does not support a complete medicine regimen in this extraction. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"dfa6a622-01ee-4fe5-9dee-5bdd2473eeac","title":"Antenatal care","issuer":"NICE","edition":"NG201, published 19 August 2021; recommendations retrieved 12 October 2026","url":"https://www.nice.org.uk/guidance/ng201/chapter/recommendations","locator":"Recommendations 1.1.4 to 1.1.10; schedule of appointments; recommendations on gestational diabetes and ultrasound scanning","primary_source":true}],"selection_rationale":"Unverified scope: Pregnant women receiving routine antenatal care for an uncomplicated singleton pregnancy; this limited extraction covers booking, selected screening tests and routine ultrasound timing."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Booking blood tests and infectious-disease screening","clinical_question":"Are anaemia, blood-group or rhesus risks, red-cell antibodies, HIV, syphilis or hepatitis B identified?","expected_finding":"Full blood count, blood group and rhesus D status, antibody testing and programme-based infectious-disease screening define baseline risks and follow-up needs.","decision_rationale":"NICE places these tests in the routine antenatal schedule so clinically important maternal and fetal risks are identified early.","timeframe":"At the first booking appointment, targeted by 10+0 weeks"},{"test":"Routine fetal ultrasound","clinical_question":"Are gestation, multiple pregnancy, aneuploidy-screening choices and fetal anatomy appropriately assessed?","expected_finding":"The 11+2 to 14+1 week scan dates the pregnancy and identifies multiple pregnancy; the 18+0 to 20+6 week scan screens fetal development and placental location.","decision_rationale":"NICE specifies these gestational windows for routine ultrasound in uncomplicated pregnancy.","timeframe":"11+2 to 14+1 weeks and 18+0 to 20+6 weeks"},{"test":"Gestational-diabetes risk assessment and oral glucose tolerance test when indicated","clinical_question":"Does the woman meet risk criteria for gestational diabetes?","expected_finding":"Risk assessment at booking identifies who should be referred for oral glucose tolerance testing.","decision_rationale":"NICE directs risk assessment at booking and OGTT referral for women at risk.","timeframe":"Risk assessment at booking; OGTT at 24+0 to 28+0 weeks when indicated"}],"evidence":{"sources":[{"id":"dfa6a622-01ee-4fe5-9dee-5bdd2473eeac","title":"Antenatal care","issuer":"NICE","edition":"NG201, published 19 August 2021; recommendations retrieved 12 October 2026","url":"https://www.nice.org.uk/guidance/ng201/chapter/recommendations","locator":"Recommendations 1.1.4 to 1.1.10; schedule of appointments; recommendations on gestational diabetes and ultrasound scanning","primary_source":true}],"selection_rationale":"Unverified scope: Pregnant women receiving routine antenatal care for an uncomplicated singleton pregnancy; this limited extraction covers booking, selected screening tests and routine ultrasound timing."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Offer the first antenatal booking appointment by 10+0 weeks and plan the routine appointment schedule according to parity and individual need.","timeframe":"By 10+0 weeks"},{"instruction":"Do not routinely offer ultrasound scans after 28 weeks in an uncomplicated singleton pregnancy; use targeted imaging when growth, presentation or wellbeing concerns arise.","timeframe":"After 28 weeks"},{"instruction":"Review gaps: This international source must be reconciled with current Saudi maternity pathways, laboratory panels, haemoglobinopathy and infectious-disease screening programmes, vaccination policy, rhesus prophylaxis, diabetes guidance and referral thresholds. It does not support a complete medicine regimen in this extraction.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"dfa6a622-01ee-4fe5-9dee-5bdd2473eeac","title":"Antenatal care","issuer":"NICE","edition":"NG201, published 19 August 2021; recommendations retrieved 12 October 2026","url":"https://www.nice.org.uk/guidance/ng201/chapter/recommendations","locator":"Recommendations 1.1.4 to 1.1.10; schedule of appointments; recommendations on gestational diabetes and ultrasound scanning","primary_source":true}],"selection_rationale":"Unverified scope: Pregnant women receiving routine antenatal care for an uncomplicated singleton pregnancy; this limited extraction covers booking, selected screening tests and routine ultrasound timing."}}]},"nonClinicalManagement":{"patientEducation":["Explain antenatal care for uncomplicated pregnancy in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Obstetrics","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"ce9316d7-2fe5-415d-a633-b0ebb79a4693","title":"Asthma","original_version_id":"ce9316d7-2fe5-415d-a633-b0ebb79a4693","expected_hash":"df836b670f37a50a5b67862e15a073f5","source_url":"https://www.nice.org.uk/guidance/ng245/chapter/recommendations","source_title":"Asthma: diagnosis, monitoring and chronic asthma management (BTS, NICE, SIGN)","issuer":"NICE","scope":"Adults, young people and children with a history suggestive of asthma; this extraction covers immediate assessment, objective diagnostic testing and monitoring rather than acute-attack dosing.","content":{"id":"ce9316d7-2fe5-415d-a633-b0ebb79a4693","title":"Asthma","specialty":"Respiratory Medicine / Primary Care","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b003","lastReviewed":"2026-10-10","pillar":"Chronic Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Airway inflammation and hyperresponsiveness cause variable bronchoconstriction and airflow limitation. Symptoms may fluctuate, while risk of severe exacerbation persists even between apparently well periods. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Airway inflammation and hyperresponsiveness cause variable bronchoconstriction and airflow limitation. Symptoms may fluctuate, while risk of severe exacerbation persists even between apparently well periods.","Clinical expression and progression vary with baseline risk, comorbidity, treatment exposure, and access to timely care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Asthma, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Silent chest or inability to speak during attack","Night waking or reliever use rising rapidly","Prior intensive-care admission or severe attack","Persistent symptoms despite verified treatment and technique"]},"differentials":[{"condition":"COPD","distinguishingFeatures":"Persistent obstruction and exposure history may suggest another or overlapping diagnosis."},{"condition":"Vocal cord dysfunction","distinguishingFeatures":"Inspiratory symptoms and targeted assessment may clarify."},{"condition":"Heart failure or anaphylaxis","distinguishingFeatures":"Assess cardiovascular or acute multisystem allergic features."}],"investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Spirometry with bronchodilator response or other objective variability testing; review exacerbations, technique, adherence and exposures.","modalityTarget":"Spirometry with bronchodilator response or other objective variability testing; review exacerbations, technique, adherence and exposures. — Asthma","targetCondition":"Asthma","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Assess comorbid rhinitis, reflux, obesity, smoking and occupational triggers when relevant.","modalityTarget":"Assess comorbid rhinitis, reflux, obesity, smoking and occupational triggers when relevant. — Cause, complication, or risk relevant to Asthma","targetCondition":"Cause, complication, or risk relevant to Asthma","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Asthma","targetCondition":"Important alternative to Asthma","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults, young people and children with a history suggestive of asthma; this extraction covers immediate assessment, objective diagnostic testing and monitoring rather than acute-attack dosing. Age-specific inhaler products, device doses, licensing, escalation steps, contraindications and acute-exacerbation regimens require the current linked algorithms, product information and Saudi formulary reconciliation. The page names ICS/formoterol but does not provide a complete product-specific dose, route, frequency, duration and contraindication set for this extraction. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"15b817a9-753f-4fc0-9d87-2d13ac1aaad2","title":"Asthma: diagnosis, monitoring and chronic asthma management (BTS, NICE, SIGN)","issuer":"NICE","edition":"NG245, published 27 November 2024; page updated November 2025","url":"https://www.nice.org.uk/guidance/ng245/chapter/recommendations","locator":"Recommendations 1.1.5 to 1.1.7, 1.2.1 to 1.2.9, 1.5.1 to 1.5.3 and 1.7.1","primary_source":true}],"selection_rationale":"Unverified scope: Adults, young people and children with a history suggestive of asthma; this extraction covers immediate assessment, objective diagnostic testing and monitoring rather than acute-attack dosing."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Blood eosinophil count or fractional exhaled nitric oxide","clinical_question":"Is there objective evidence supporting asthma in an adult with a suggestive history?","expected_finding":"An eosinophil count above the laboratory reference range or FeNO at least 50 ppb supports an adult diagnosis.","decision_rationale":"NICE recommends eosinophils or FeNO as the first objective step for adults.","timeframe":"At diagnostic assessment, before inhaled corticosteroid treatment when feasible"},{"test":"Bronchodilator reversibility with spirometry","clinical_question":"Is reversible airflow obstruction present when eosinophils or FeNO do not confirm asthma?","expected_finding":"An FEV1 increase of at least 12% and 200 mL, or at least 10% of predicted normal FEV1, supports diagnosis in adults.","decision_rationale":"NICE uses spirometric bronchodilator reversibility as the next adult diagnostic step.","timeframe":"Promptly when initial objective testing is non-diagnostic"},{"test":"Peak expiratory flow variability or bronchial challenge","clinical_question":"Can asthma be confirmed when spirometry is delayed or prior objective tests are non-diagnostic?","expected_finding":"PEF variability of at least 20% over twice-daily measurements for 2 weeks supports diagnosis; bronchial hyper-responsiveness supports diagnosis when asthma remains suspected.","decision_rationale":"NICE provides sequential alternatives when earlier testing is unavailable or inconclusive.","timeframe":"PEF twice daily for 2 weeks; challenge testing after unresolved diagnostic uncertainty"}],"evidence":{"sources":[{"id":"15b817a9-753f-4fc0-9d87-2d13ac1aaad2","title":"Asthma: diagnosis, monitoring and chronic asthma management (BTS, NICE, SIGN)","issuer":"NICE","edition":"NG245, published 27 November 2024; page updated November 2025","url":"https://www.nice.org.uk/guidance/ng245/chapter/recommendations","locator":"Recommendations 1.1.5 to 1.1.7, 1.2.1 to 1.2.9, 1.5.1 to 1.5.3 and 1.7.1","primary_source":true}],"selection_rationale":"Unverified scope: Adults, young people and children with a history suggestive of asthma; this extraction covers immediate assessment, objective diagnostic testing and monitoring rather than acute-attack dosing."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Treat immediately if the person is acutely unwell or highly symptomatic and perform available objective tests without delaying treatment.","timeframe":"Immediately at acute presentation"},{"instruction":"Monitor symptoms, reliever use, oral corticosteroid courses and urgent-care attendance at every asthma review; check adherence and inhaler technique.","timeframe":"At every asthma review"},{"instruction":"Review gaps: Age-specific inhaler products, device doses, licensing, escalation steps, contraindications and acute-exacerbation regimens require the current linked algorithms, product information and Saudi formulary reconciliation. The page names ICS/formoterol but does not provide a complete product-specific dose, route, frequency, duration and contraindication set for this extraction.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"15b817a9-753f-4fc0-9d87-2d13ac1aaad2","title":"Asthma: diagnosis, monitoring and chronic asthma management (BTS, NICE, SIGN)","issuer":"NICE","edition":"NG245, published 27 November 2024; page updated November 2025","url":"https://www.nice.org.uk/guidance/ng245/chapter/recommendations","locator":"Recommendations 1.1.5 to 1.1.7, 1.2.1 to 1.2.9, 1.5.1 to 1.5.3 and 1.7.1","primary_source":true}],"selection_rationale":"Unverified scope: Adults, young people and children with a history suggestive of asthma; this extraction covers immediate assessment, objective diagnostic testing and monitoring rather than acute-attack dosing."}}]},"nonClinicalManagement":{"patientEducation":["Explain asthma in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Respiratory Medicine / Primary Care","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"a1020000-0000-4000-8000-000000000001","title":"Atrial Fibrillation [Adapted from NICE]","original_version_id":"a1020000-0000-4000-8000-000000000001","expected_hash":"f423a2152c1ccf8960c43bf43048edfb","source_url":"https://www.nice.org.uk/guidance/ng196/chapter/recommendations","source_title":"Atrial fibrillation: diagnosis and management","issuer":"NICE","scope":"Adults with suspected or confirmed atrial fibrillation; limited to confirmation, stroke and bleeding risk, cardiac assessment and high-level treatment selection.","content":{"id":"a1020000-0000-4000-8000-000000000001","title":"Atrial Fibrillation [Adapted from NICE]","specialty":"Cardiology and Internal Medicine","authority":"NICE","status":"draft","version":"official-extraction-2026-10-11-b003","lastReviewed":"2021-06-30","pillar":"Chronic Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Atrial fibrillation is a supraventricular tachyarrhythmia with disorganised atrial activation and ineffective atrial contraction. Irregular ventricular conduction can cause symptoms or tachycardia-mediated dysfunction, while atrial blood stasis promotes thrombus formation and systemic embolism.","keyMechanisms":["Ectopic atrial triggers and a susceptible atrial substrate sustain chaotic electrical activation.","Loss of coordinated atrial contraction and irregular atrioventricular conduction reduce haemodynamic efficiency.","Blood stasis, endothelial dysfunction and prothrombotic factors increase left-atrial thrombus and stroke risk.","Hypertension, heart failure, valve disease, thyroid disease, obesity, sleep apnoea and alcohol can promote onset or recurrence."]},"presentation":{"symptoms":["Palpitations or an irregular heartbeat","Breathlessness or reduced exercise tolerance","Fatigue, dizziness, presyncope or syncope","Chest discomfort or presentation with stroke or transient ischaemic attack"],"physicalSigns":["Irregularly irregular pulse","Variable first heart sound and pulse deficit","Tachycardia or, with conduction disease or medication, bradycardia","Signs of heart failure, valve disease or systemic embolism"],"redFlags":["Haemodynamic instability, shock, ongoing myocardial ischaemia or severe pulmonary oedema","New focal neurological deficit suggesting stroke","Syncope with a very rapid or very slow ventricular response","Acute decompensated heart failure or pre-excited atrial fibrillation"]},"differentials":[{"condition":"Atrial flutter with variable block","distinguishingFeatures":"Organised flutter activity on electrocardiogram, often with a regular or patterned ventricular response."},{"condition":"Frequent atrial ectopy","distinguishingFeatures":"Discrete premature P waves with intervening sinus rhythm rather than sustained fibrillatory activity."},{"condition":"Multifocal atrial tachycardia","distinguishingFeatures":"At least three P-wave morphologies and an isoelectric baseline, often in severe pulmonary disease."},{"condition":"Sinus tachycardia with artefact","distinguishingFeatures":"Consistent P waves and a physiological trigger; careful lead review separates artefact from atrial activity."}],"investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"12-lead electrocardiogram","modalityTarget":"12-lead electrocardiogram — Atrial fibrillation","targetCondition":"Atrial fibrillation","expectedFinding":"Irregularly irregular R-R intervals with no consistent discrete P waves.","clinicalRationale":"Provides rhythm confirmation and identifies conduction, ischaemic or pre-excitation features that alter management."},{"tier":"specializedAdjunctive","testName":"Ambulatory electrocardiographic monitoring","modalityTarget":"Ambulatory electrocardiographic monitoring — Paroxysmal atrial fibrillation","targetCondition":"Paroxysmal atrial fibrillation","expectedFinding":"Intermittent electrocardiographically documented atrial fibrillation during symptoms or silent episodes.","clinicalRationale":"Monitoring duration should match symptom frequency when the resting electrocardiogram is normal."},{"tier":"specializedAdjunctive","testName":"Transthoracic echocardiography when indicated","modalityTarget":"Transthoracic echocardiography when indicated — Structural or functional heart disease","targetCondition":"Structural or functional heart disease","expectedFinding":"Atrial enlargement, ventricular dysfunction, valve disease or another finding that changes management.","clinicalRationale":"Supports rhythm-control planning, heart-failure assessment and selected refinement of thromboembolic risk."}],"ruleOut":[{"tier":"laboratory","testName":"Thyroid function testing","modalityTarget":"Thyroid function testing — Thyrotoxicosis","targetCondition":"Thyrotoxicosis","expectedFinding":"No biochemical hyperthyroidism, or a reversible driver is identified.","clinicalRationale":"Thyroid disease can precipitate atrial fibrillation and requires concurrent treatment."},{"tier":"laboratory","testName":"Electrolytes, renal and liver function","modalityTarget":"Electrolytes, renal and liver function — Metabolic precipitant or medicine contraindication","targetCondition":"Metabolic precipitant or medicine contraindication","expectedFinding":"No correctable electrolyte disturbance; organ function is adequate for the selected medicine or prompts adjustment.","clinicalRationale":"Identifies reversible contributors and is essential before anticoagulant or antiarrhythmic selection."},{"tier":"laboratory","testName":"Acute coronary and pulmonary assessment when clinically indicated","modalityTarget":"Acute coronary and pulmonary assessment when clinically indicated — Acute coronary syndrome or pulmonary embolism","targetCondition":"Acute coronary syndrome or pulmonary embolism","expectedFinding":"No acute ischaemic or thromboembolic trigger, or one is identified and treated through its urgent pathway.","clinicalRationale":"New atrial fibrillation may be secondary to another time-critical condition."}]},"clinicalManagement":[{"id":"stability","title":"Assess stability and reversible triggers","timeframe":"Immediately at acute presentation","actions":["Assess airway, breathing, circulation, ischaemia, heart failure and neurological status.","Obtain a 12-lead electrocardiogram and correct hypoxia, electrolyte disturbance or another precipitant.","Seek senior cardiology/critical-care support for unstable or pre-excited atrial fibrillation."],"branches":[{"condition":"Life-threatening haemodynamic instability attributable to atrial fibrillation","actions":["Perform urgent synchronised electrical cardioversion under the locally approved resuscitation and sedation protocol.","Do not delay emergency cardioversion solely to complete routine anticoagulation assessment."]},{"condition":"No life-threatening instability","actions":["Proceed to symptom, duration, rate/rhythm and thromboembolic-risk assessment."]}]},{"id":"risk","title":"Assess stroke and bleeding risks","timeframe":"At diagnosis and whenever risk factors change","actions":["Use CHA2DS2-VASc for stroke risk and a validated bleeding-risk tool such as ORBIT.","Identify and modify reversible bleeding risks rather than using a bleeding score alone to withhold anticoagulation.","Discuss absolute benefits, bleeding harms and patient preferences using shared decision making."]},{"id":"anticoagulation","title":"Prevent thromboembolism","timeframe":"Promptly after risk assessment","actions":["Offer an SFDA-authorised generic direct-acting oral anticoagulant, such as dabigatran etexilate or rivaroxaban, when indicated and suitable; select using renal function, interactions, adherence and the local formulary.","Use warfarin when a direct-acting anticoagulant is contraindicated, unsuitable, or the clinical condition specifically requires a vitamin-K antagonist.","Do not use antiplatelet monotherapy solely for atrial-fibrillation stroke prevention.","Use current SFDA labelling and the local formulary for all dosing; this record is not a prescribing source."]},{"id":"rate-rhythm","title":"Choose rate or rhythm control","timeframe":"During initial management and at symptom review","actions":["Use rate control first for many stable patients, with a generic beta-blocker or rate-limiting calcium-channel blocker selected for comorbidity and contraindications.","Consider rhythm control for persistent symptoms, a reversible cause, new onset, atrial flutter suitable for ablation or heart failure thought to be driven by the arrhythmia.","Avoid a rate-limiting calcium-channel blocker in acute decompensated heart failure and obtain specialist advice.","Assess anticoagulation requirements around cardioversion according to rhythm duration and the current protocol."]},{"id":"specialist","title":"Escalate persistent or complex disease","timeframe":"Promptly when initial treatment fails or complexity is identified","actions":["Refer for cardiology review when symptoms remain uncontrolled, recurrence follows cardioversion or antiarrhythmic/ablation decisions are needed.","Consider catheter ablation through specialist shared decision making for eligible symptomatic patients.","Reassess stroke prevention after rhythm restoration because apparent sinus rhythm does not automatically remove thromboembolic risk."]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults with suspected or confirmed atrial fibrillation; limited to confirmation, stroke and bleeding risk, cardiac assessment and high-level treatment selection. Drug choice and dosing depend on renal function, age, weight, interacting medicines, valvular disease and product criteria. The source names anticoagulants and rate/rhythm medicines but this extraction does not provide a complete dose, route, frequency, duration and contraindication set. Saudi formulary and emergency cardioversion pathways require reconciliation. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"15525037-448b-4ce5-8106-466995edcc0a","title":"Atrial fibrillation: diagnosis and management","issuer":"NICE","edition":"NG196, published 27 April 2021; last updated 30 June 2021","url":"https://www.nice.org.uk/guidance/ng196/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.3.3, 1.5.1, 1.6.1 to 1.6.6 and 1.7.1 to 1.8.5","primary_source":true}],"selection_rationale":"Unverified scope: Adults with suspected or confirmed atrial fibrillation; limited to confirmation, stroke and bleeding risk, cardiac assessment and high-level treatment selection."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"12-lead ECG and ambulatory ECG when needed","clinical_question":"Is atrial fibrillation present and is paroxysmal AF being missed by a single tracing?","expected_finding":"A 12-lead ECG confirms AF after an irregular pulse; 24-hour or longer event monitoring may detect paroxysmal AF according to symptom frequency.","decision_rationale":"NICE defines ECG confirmation and symptom-frequency-based ambulatory monitoring.","timeframe":"At suspicion; ambulatory monitoring promptly when the 12-lead ECG is non-diagnostic"},{"test":"CHA2DS2-VASc and ORBIT risk assessment","clinical_question":"What are the person's stroke and absolute major-bleeding risks?","expected_finding":"The recorded scores support shared decisions on anticoagulation and modifiable bleeding risks.","decision_rationale":"NICE recommends CHA2DS2-VASc for stroke risk and ORBIT for bleeding risk.","timeframe":"At diagnosis and when clinical circumstances change"},{"test":"Transthoracic or transoesophageal echocardiography when indicated","clinical_question":"Is structural or functional disease present and would imaging change long-term management or cardioversion planning?","expected_finding":"Imaging may identify structural disease, refine management or support TOE-guided cardioversion.","decision_rationale":"NICE limits echocardiography to defined management-changing indications rather than routine stroke-risk stratification alone.","timeframe":"Before management decisions that depend on cardiac structure or cardioversion strategy"}],"evidence":{"sources":[{"id":"15525037-448b-4ce5-8106-466995edcc0a","title":"Atrial fibrillation: diagnosis and management","issuer":"NICE","edition":"NG196, published 27 April 2021; last updated 30 June 2021","url":"https://www.nice.org.uk/guidance/ng196/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.3.3, 1.5.1, 1.6.1 to 1.6.6 and 1.7.1 to 1.8.5","primary_source":true}],"selection_rationale":"Unverified scope: Adults with suspected or confirmed atrial fibrillation; limited to confirmation, stroke and bleeding risk, cardiac assessment and high-level treatment selection."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Use clinical risk profiles and patient preferences when discussing anticoagulation; offer a direct-acting oral anticoagulant at CHA2DS2-VASc 2 or above and consider one for men with score 1, subject to suitability and current product guidance.","timeframe":"After risk assessment"},{"instruction":"Refer promptly for specialist management when treatment fails to control symptoms, within 4 weeks of failed treatment or recurrence after cardioversion.","timeframe":"Within 4 weeks"},{"instruction":"Review gaps: Drug choice and dosing depend on renal function, age, weight, interacting medicines, valvular disease and product criteria. The source names anticoagulants and rate/rhythm medicines but this extraction does not provide a complete dose, route, frequency, duration and contraindication set. Saudi formulary and emergency cardioversion pathways require reconciliation.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"15525037-448b-4ce5-8106-466995edcc0a","title":"Atrial fibrillation: diagnosis and management","issuer":"NICE","edition":"NG196, published 27 April 2021; last updated 30 June 2021","url":"https://www.nice.org.uk/guidance/ng196/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.3.3, 1.5.1, 1.6.1 to 1.6.6 and 1.7.1 to 1.8.5","primary_source":true}],"selection_rationale":"Unverified scope: Adults with suspected or confirmed atrial fibrillation; limited to confirmation, stroke and bleeding risk, cardiac assessment and high-level treatment selection."}}]},"nonClinicalManagement":{"patientEducation":["Explain the irregular rhythm, symptom-control options and the distinct purpose of anticoagulation.","Teach stroke warning signs and the need for immediate emergency assessment.","Provide medicine-specific bleeding, missed-dose, procedure and interaction advice using approved Saudi information."],"lifestyleAndDiet":["Support weight management, regular physical activity and control of blood pressure and diabetes.","Screen for and treat obstructive sleep apnoea when suspected.","Reduce excessive alcohol and stimulant exposure and stop smoking.","For warfarin, advise consistency rather than avoidance of vitamin-K-containing foods and arrange INR education."],"mdtReferrals":["Cardiology or electrophysiology for rhythm-control and ablation decisions","Anticoagulation or clinical pharmacy service for medicine selection, interactions and adherence","Stroke service for any acute or previous cerebrovascular event","Sleep medicine and weight-management services where relevant"],"dischargeCriteria":["Haemodynamics are stable and acute triggers have been addressed.","A rate/rhythm strategy and anticoagulation decision are documented with renal-function-appropriate prescribing.","The patient understands stroke and bleeding precautions and has timely follow-up."],"followUpPlan":"Review symptoms, pulse/rate, blood pressure, anticoagulant adherence, bleeding risk and renal function at a medicine-appropriate interval; reassess stroke risk at least annually and whenever age or comorbidity changes."}}},{"id":"a1010000-0000-4000-8000-000000000006","title":"Breast Cancer Management","original_version_id":"a1010000-0000-4000-8000-000000000006","expected_hash":"61ff878d9c62cfc2ec9253a2ffe9c6e4","source_url":"https://www.nice.org.uk/guidance/ng101/chapter/recommendations","source_title":"Early and locally advanced breast cancer: diagnosis and management","issuer":"NICE","scope":"People with newly diagnosed early or locally advanced breast cancer; limited to pretreatment staging, tumour biomarkers, multidisciplinary treatment selection and surveillance.","content":{"id":"a1010000-0000-4000-8000-000000000006","title":"Breast Cancer Management","specialty":"Medical Oncology, Breast Surgery and Radiation Oncology","authority":"SHC","status":"draft","version":"official-extraction-2026-10-11-b003","lastReviewed":"2018-01-01","pillar":"Planned Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Breast cancer comprises malignant epithelial tumours with heterogeneous hormone-receptor, HER2 and genomic biology. Disease may remain in situ, invade breast and regional lymphatics, or spread haematogenously to bone, liver, lung and brain; biology and stage jointly determine treatment and prognosis.","keyMechanisms":["Accumulated genomic and epigenetic alterations enable uncontrolled proliferation and invasion.","Oestrogen/progesterone-receptor signalling and HER2 amplification define actionable biological subsets.","Lymphatic spread commonly involves axillary and regional nodes.","Tumour heterogeneity and treatment selection pressure can change receptor status in recurrent disease."]},"presentation":{"symptoms":["New breast or axillary lump","Nipple retraction or bloody discharge","Persistent focal breast change or skin dimpling","Bone pain, breathlessness, neurological symptoms or weight loss in advanced disease"],"physicalSigns":["Discrete breast mass or asymmetric thickening","Peau d'orange, ulceration or inflammatory change","Nipple inversion or eczematous nipple lesion","Palpable axillary or supraclavicular nodes"],"redFlags":["Rapidly progressive inflammatory breast change","Spinal pain with weakness, sensory change or bladder/bowel dysfunction","New focal neurological deficit, seizure or raised intracranial-pressure symptoms","Visceral crisis with organ dysfunction requiring rapid oncology assessment"]},"differentials":[{"condition":"Fibroadenoma","distinguishingFeatures":"Often mobile, well-circumscribed and benign on age-appropriate imaging, but tissue diagnosis is required when assessment is discordant."},{"condition":"Breast cyst","distinguishingFeatures":"Fluid-filled lesion on ultrasound with resolution after aspiration in selected cases."},{"condition":"Mastitis or abscess","distinguishingFeatures":"Pain, erythema, fever and a collection; non-resolution requires investigation for inflammatory malignancy."},{"condition":"Fat necrosis","distinguishingFeatures":"History of trauma or surgery with characteristic imaging, although biopsy may be needed if suspicious."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Triple assessment","modalityTarget":"Triple assessment — Breast malignancy","targetCondition":"Breast malignancy","expectedFinding":"Concordant suspicious clinical examination, mammography/ultrasound and core-biopsy histology.","clinicalRationale":"Integrates anatomy and tissue diagnosis while minimising false reassurance from any single test."},{"tier":"laboratory","testName":"Histopathology with ER, PR and HER2 testing","modalityTarget":"Histopathology with ER, PR and HER2 testing — Invasive breast-cancer subtype","targetCondition":"Invasive breast-cancer subtype","expectedFinding":"Malignant morphology with grade and validated receptor status.","clinicalRationale":"Confirms diagnosis and directs endocrine, anti-HER2 and chemotherapy decisions."},{"tier":"laboratory","testName":"Stage-directed imaging","modalityTarget":"Stage-directed imaging — Regional or distant metastatic disease","targetCondition":"Regional or distant metastatic disease","expectedFinding":"Imaging defines tumour, nodal and metastatic burden when stage or symptoms justify it.","clinicalRationale":"Avoids indiscriminate staging in low-risk disease while identifying treatment-changing metastases."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Image-guided core biopsy of a suspicious benign-appearing lesion","modalityTarget":"Image-guided core biopsy of a suspicious benign-appearing lesion — Benign breast disease","targetCondition":"Benign breast disease","expectedFinding":"Pathology is benign and concordant with clinical and imaging findings.","clinicalRationale":"Discordance requires repeat sampling or excision rather than simple reassurance."},{"tier":"laboratory","testName":"Targeted imaging of new symptoms","modalityTarget":"Targeted imaging of new symptoms — Metastatic complication","targetCondition":"Metastatic complication","expectedFinding":"No metastasis explaining the symptom, or a lesion is identified for urgent management.","clinicalRationale":"Routine surveillance imaging in asymptomatic early-stage survivors is not a substitute for symptom-led assessment."}]},"clinicalManagement":[{"id":"confirm-stage","title":"Confirm pathology and stage","timeframe":"Before definitive treatment","actions":["Obtain adequate core tissue and report histological type, grade and ER, PR and HER2 status.","Complete stage-appropriate imaging and assess performance status, comorbidities and baseline organ function.","Arrange genetic and fertility counselling when clinical criteria are met."]},{"id":"mdt-plan","title":"Agree a multidisciplinary plan","timeframe":"After diagnostic work-up","actions":["Discuss every new case in a breast multidisciplinary conference.","Integrate stage, biology, patient goals, surgical feasibility and treatment toxicities.","Record sequence of surgery, systemic therapy and radiotherapy with responsible teams."]},{"id":"local-therapy","title":"Deliver local-regional therapy","timeframe":"According to stage and treatment sequence","actions":["Offer breast-conserving surgery or mastectomy according to disease extent, contraindications and informed preference.","Stage the axilla using the appropriate sentinel-node or nodal procedure.","Plan radiotherapy according to surgical approach, margins, nodal involvement and recurrence risk."]},{"id":"systemic-therapy","title":"Select biology-directed systemic therapy","timeframe":"Neoadjuvant or adjuvant as agreed by MDT","actions":["Use endocrine therapy for hormone-receptor-positive disease when indicated.","Use generic anti-HER2 therapy for eligible HER2-positive disease with cardiac monitoring.","Select chemotherapy and any contemporary targeted or immunotherapy only through the current approved oncology protocol."],"branches":[{"condition":"Locally advanced or inflammatory disease","actions":["Prioritise neoadjuvant systemic therapy and serial response assessment.","Proceed to local therapy if disease becomes operable and the MDT confirms benefit."]}]},{"id":"surveillance","title":"Survivorship or advanced-disease review","timeframe":"After initial treatment and throughout follow-up","actions":["Use interval history, examination and mammography of retained breast tissue according to policy.","Manage endocrine, bone, cardiac, menopausal and lymphoedema effects.","For metastatic disease, prioritise symptom control, quality of life and biology-directed therapy with early supportive care."]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. People with newly diagnosed early or locally advanced breast cancer; limited to pretreatment staging, tumour biomarkers, multidisciplinary treatment selection and surveillance. Cancer treatment must be subtype-, stage-, comorbidity- and protocol-specific. The source names systemic therapies and schedules but this extraction does not reproduce full regimens, doses, routes, supportive care, interactions or contraindications. Current Saudi oncology protocols, licensing and multidisciplinary review are mandatory before approval. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"39c03319-3c9d-436f-8e17-ece0aa8b9114","title":"Early and locally advanced breast cancer: diagnosis and management","issuer":"NICE","edition":"NG101, published 18 July 2018; updated April 2025","url":"https://www.nice.org.uk/guidance/ng101/chapter/recommendations","locator":"Recommendations 1.2.1 to 1.3.5, treatment sections 1.8 to 1.14 and follow-up recommendations 1.15.1 to 1.15.4","primary_source":true}],"selection_rationale":"Unverified scope: People with newly diagnosed early or locally advanced breast cancer; limited to pretreatment staging, tumour biomarkers, multidisciplinary treatment selection and surveillance."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Pretreatment axillary ultrasound with ultrasound-guided needle sampling when abnormal","clinical_question":"Is regional nodal disease present before treatment planning?","expected_finding":"Abnormal nodes sampled under ultrasound may confirm nodal metastasis and alter surgical or systemic planning.","decision_rationale":"NICE recommends ultrasound evaluation of the axilla and guided sampling of abnormal nodes.","timeframe":"Before definitive treatment planning"},{"test":"ER, PR and HER2 status at initial histopathological diagnosis","clinical_question":"Which biologic subtype guides systemic treatment?","expected_finding":"Quantitative, quality-assured ER, PR and HER2 results classify the tumour and inform treatment selection.","decision_rationale":"NICE recommends simultaneous biomarker assessment so results are available to preoperative and postoperative MDTs.","timeframe":"At initial histopathological diagnosis"},{"test":"Breast MRI only for defined preoperative indications","clinical_question":"Is disease extent unclear on examination, mammography and ultrasound, or is breast-conserving surgery planning otherwise uncertain?","expected_finding":"MRI may better define extent in selected patients; routine MRI is not recommended.","decision_rationale":"NICE restricts preoperative MRI to management-changing uncertainty.","timeframe":"Before surgery when specified indications are present"}],"evidence":{"sources":[{"id":"39c03319-3c9d-436f-8e17-ece0aa8b9114","title":"Early and locally advanced breast cancer: diagnosis and management","issuer":"NICE","edition":"NG101, published 18 July 2018; updated April 2025","url":"https://www.nice.org.uk/guidance/ng101/chapter/recommendations","locator":"Recommendations 1.2.1 to 1.3.5, treatment sections 1.8 to 1.14 and follow-up recommendations 1.15.1 to 1.15.4","primary_source":true}],"selection_rationale":"Unverified scope: People with newly diagnosed early or locally advanced breast cancer; limited to pretreatment staging, tumour biomarkers, multidisciplinary treatment selection and surveillance."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Discuss systemic anticancer, surgical and radiotherapy options in a specialist multidisciplinary team using stage, receptor status, comorbidity, toxicity and patient preference.","timeframe":"Before treatment starts and when pathology changes the plan"},{"instruction":"Offer annual mammography for 5 years after breast cancer or DCIS treatment and avoid routine ultrasound or MRI surveillance unless another indication exists.","timeframe":"Annually for 5 years after treatment"},{"instruction":"Review gaps: Cancer treatment must be subtype-, stage-, comorbidity- and protocol-specific. The source names systemic therapies and schedules but this extraction does not reproduce full regimens, doses, routes, supportive care, interactions or contraindications. Current Saudi oncology protocols, licensing and multidisciplinary review are mandatory before approval.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"39c03319-3c9d-436f-8e17-ece0aa8b9114","title":"Early and locally advanced breast cancer: diagnosis and management","issuer":"NICE","edition":"NG101, published 18 July 2018; updated April 2025","url":"https://www.nice.org.uk/guidance/ng101/chapter/recommendations","locator":"Recommendations 1.2.1 to 1.3.5, treatment sections 1.8 to 1.14 and follow-up recommendations 1.15.1 to 1.15.4","primary_source":true}],"selection_rationale":"Unverified scope: People with newly diagnosed early or locally advanced breast cancer; limited to pretreatment staging, tumour biomarkers, multidisciplinary treatment selection and surveillance."}}]},"nonClinicalManagement":{"patientEducation":["Explain stage, receptor status, treatment intent and the role of each modality in plain language.","Discuss expected adverse effects, fertility, sexual health, pregnancy considerations and when to seek urgent care.","Provide individualised information on recurrence symptoms without encouraging harmful routine self-testing."],"lifestyleAndDiet":["Support regular physical activity and maintenance of a healthy body composition during and after treatment.","Provide dietetic advice for treatment-related weight change, nausea or malnutrition.","Offer smoking-cessation support and advise avoidance of unreviewed supplements that may interact with therapy."],"mdtReferrals":["Breast surgeon, medical oncologist, radiation oncologist and breast-care nurse","Genetics for hereditary-risk criteria","Fertility service before gonadotoxic treatment when relevant","Physiotherapy/lymphoedema, psycho-oncology and palliative care according to need"],"dischargeCriteria":["The diagnosis, stage, receptor profile and MDT plan are documented.","Acute treatment complications are controlled and the patient has clear contacts.","Surveillance ownership, medicine monitoring and urgent symptom pathways are explicit."],"followUpPlan":"Follow the current Saudi oncology surveillance schedule, including clinical review and mammography where breast tissue remains; monitor therapy-specific cardiac, bone, gynaecological and lymphoedema risks and investigate new symptoms promptly."}}},{"id":"d2743507-415a-4bc7-8857-3604c97bab42","title":"Breast Cancer Screening Discussion","original_version_id":"d2743507-415a-4bc7-8857-3604c97bab42","expected_hash":"ca3a8ea7a7783baaacb2519c05de9489","source_url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/breast-cancer-screening","source_title":"USPSTF Breast Cancer: Screening Final Recommendation Statement","issuer":"Other","scope":"Women and other persons assigned female at birth aged 40 years or older at average risk, including those with family history or dense breasts but excluding defined high-risk genetic, prior chest-radiation, prior breast-cancer and high-risk-lesion groups.","content":{"id":"d2743507-415a-4bc7-8857-3604c97bab42","title":"Breast Cancer Screening Discussion","specialty":"Primary Care / Public Health","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b003","lastReviewed":"2026-10-10","pillar":"Keep Well","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Screening aims to detect clinically important cancer earlier in asymptomatic populations but can cause false positives, overdiagnosis, anxiety, and unnecessary procedures. Absolute benefit varies with baseline risk and age. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Screening aims to detect clinically important cancer earlier in asymptomatic populations but can cause false positives, overdiagnosis, anxiety, and unnecessary procedures. Absolute benefit varies with baseline risk and age.","Clinical expression and progression vary with baseline risk, comorbidity, treatment exposure, and access to timely care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Breast Cancer Screening Discussion, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["New lump, nipple retraction/discharge or skin change is diagnostic assessment, not screening","Strong hereditary pattern or young affected relative","Prior chest irradiation or high-risk lesion","Pregnancy/lactation with new symptom"]},"differentials":[{"condition":"Symptomatic breast disease","distinguishingFeatures":"Needs diagnostic examination/imaging rather than routine screening."},{"condition":"High-risk inherited susceptibility","distinguishingFeatures":"May need genetics and a different imaging pathway."},{"condition":"Benign palpable change","distinguishingFeatures":"Still requires assessment based on age and finding."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Structured personal/family history and breast symptom review; check current Saudi screening eligibility and prior imaging.","modalityTarget":"Structured personal/family history and breast symptom review; check current Saudi screening eligibility and prior imaging. — Breast Cancer Screening Discussion","targetCondition":"Breast Cancer Screening Discussion","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Use diagnostic imaging or referral for symptoms or high-risk history; screening modality follows current national programme.","modalityTarget":"Use diagnostic imaging or referral for symptoms or high-risk history; screening modality follows current national programme. — Cause, complication, or risk relevant to Breast Cancer Screening Discussion","targetCondition":"Cause, complication, or risk relevant to Breast Cancer Screening Discussion","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Breast Cancer Screening Discussion","targetCondition":"Important alternative to Breast Cancer Screening Discussion","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Women and other persons assigned female at birth aged 40 years or older at average risk, including those with family history or dense breasts but excluding defined high-risk genetic, prior chest-radiation, prior breast-cancer and high-risk-lesion groups. This United States recommendation is not a Saudi national screening pathway. It finds insufficient evidence for screening at age 75 or older and for supplemental ultrasound or MRI after a negative mammogram in dense breasts. Saudi eligibility, interval, modality, referral capacity and high-risk pathways require reconciliation. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"7bea256b-fae3-4b29-8a7a-8f21db084f6a","title":"USPSTF Breast Cancer: Screening Final Recommendation Statement","issuer":"Other","edition":"Final recommendation, 30 April 2024","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/breast-cancer-screening","locator":"Recommendation Summary and Practice Considerations: patient population, assessment of risk and screening tests","primary_source":true}],"selection_rationale":"Unverified scope: Women and other persons assigned female at birth aged 40 years or older at average risk, including those with family history or dense breasts but excluding defined high-risk genetic, prior chest-radiation, prior breast-cancer and high-risk-lesion groups."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Biennial screening mammography","clinical_question":"Is an average-risk person aged 40 to 74 eligible for routine breast-cancer screening?","expected_finding":"The USPSTF recommends mammography every 2 years for women aged 40 to 74.","decision_rationale":"The Task Force judged this strategy to have moderate net benefit for this population.","timeframe":"Every 2 years from age 40 through 74"},{"test":"Risk and scope assessment before applying the routine recommendation","clinical_question":"Does the person have a genetic syndrome, prior high-dose chest radiation, previous breast cancer or a high-risk breast lesion requiring a different pathway?","expected_finding":"A high-risk feature places the person outside the scope of the routine USPSTF recommendation.","decision_rationale":"The recommendation explicitly excludes these high-risk groups.","timeframe":"Before routine screening is selected"}],"evidence":{"sources":[{"id":"7bea256b-fae3-4b29-8a7a-8f21db084f6a","title":"USPSTF Breast Cancer: Screening Final Recommendation Statement","issuer":"Other","edition":"Final recommendation, 30 April 2024","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/breast-cancer-screening","locator":"Recommendation Summary and Practice Considerations: patient population, assessment of risk and screening tests","primary_source":true}],"selection_rationale":"Unverified scope: Women and other persons assigned female at birth aged 40 years or older at average risk, including those with family history or dense breasts but excluding defined high-risk genetic, prior chest-radiation, prior breast-cancer and high-risk-lesion groups."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Discuss expected benefit, false positives, overdiagnosis and the limits of evidence, then use the current local programme for ordering and follow-up.","timeframe":"Before screening"},{"instruction":"Use clinical judgement for people aged 75 or older and for supplemental ultrasound or MRI in dense breasts because evidence is insufficient.","timeframe":"When either situation arises"},{"instruction":"Review gaps: This United States recommendation is not a Saudi national screening pathway. It finds insufficient evidence for screening at age 75 or older and for supplemental ultrasound or MRI after a negative mammogram in dense breasts. Saudi eligibility, interval, modality, referral capacity and high-risk pathways require reconciliation.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"7bea256b-fae3-4b29-8a7a-8f21db084f6a","title":"USPSTF Breast Cancer: Screening Final Recommendation Statement","issuer":"Other","edition":"Final recommendation, 30 April 2024","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/breast-cancer-screening","locator":"Recommendation Summary and Practice Considerations: patient population, assessment of risk and screening tests","primary_source":true}],"selection_rationale":"Unverified scope: Women and other persons assigned female at birth aged 40 years or older at average risk, including those with family history or dense breasts but excluding defined high-risk genetic, prior chest-radiation, prior breast-cancer and high-risk-lesion groups."}}]},"nonClinicalManagement":{"patientEducation":["Explain breast cancer screening discussion in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Primary Care / Public Health","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"cc78da1f-1df1-477a-b691-56ef783e4054","title":"Cancer Pain Assessment and Support","original_version_id":"cc78da1f-1df1-477a-b691-56ef783e4054","expected_hash":"547893fc74fa15628d10948f0b13f1a6","source_url":"https://www.nice.org.uk/guidance/cg140/chapter/recommendations","source_title":"Palliative care for adults: strong opioids for pain relief","issuer":"NICE","scope":"Adults with advanced and progressive disease who require strong opioids for pain, with the dosing extraction limited to opioid-naive patients without renal or hepatic comorbidity during initial titration.","content":{"id":"cc78da1f-1df1-477a-b691-56ef783e4054","title":"Cancer Pain Assessment and Support","specialty":"Palliative Medicine / Oncology","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b003","lastReviewed":"2026-10-10","pillar":"Palliative Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Cancer pain may arise from tissue injury, inflammation, bone destruction, nerve infiltration, treatment, or interacting mechanisms. Relief requires repeated assessment of both pain and function while minimising adverse effects. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Cancer pain may arise from tissue injury, inflammation, bone destruction, nerve infiltration, treatment, or interacting mechanisms. Relief requires repeated assessment of both pain and function while minimising adverse effects.","Clinical expression and progression vary with baseline risk, comorbidity, treatment exposure, and access to timely care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Cancer Pain Assessment and Support, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["New weakness, sensory loss, or bladder/bowel dysfunction","Sudden severe pain suggesting fracture or cord compression","Uncontrolled pain or medication toxicity","New delirium, respiratory suppression, or falls"]},"differentials":[{"condition":"Neuropathic pain","distinguishingFeatures":"Burning, shooting, allodynia, or sensory change may indicate nerve involvement."},{"condition":"Incident/bone pain","distinguishingFeatures":"Movement-related focal pain suggests structural complication."},{"condition":"Treatment-related pain","distinguishingFeatures":"Temporal relation to therapy or procedure informs cause."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Pain and function assessment, neurological examination, medication reconciliation, renal/hepatic review; imaging when structural complication is suspected.","modalityTarget":"Pain and function assessment, neurological examination, medication reconciliation, renal/hepatic review; imaging when structural complication is suspected. — Cancer Pain Assessment and Support","targetCondition":"Cancer Pain Assessment and Support","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Use local palliative formulary and specialist advice for medicine choices, titration and rescue plan.","modalityTarget":"Use local palliative formulary and specialist advice for medicine choices, titration and rescue plan. — Cause, complication, or risk relevant to Cancer Pain Assessment and Support","targetCondition":"Cause, complication, or risk relevant to Cancer Pain Assessment and Support","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Cancer Pain Assessment and Support","targetCondition":"Important alternative to Cancer Pain Assessment and Support","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[{"indication":"Background pain requiring a strong opioid during initial titration","patientGroup":"Opioid-naive adults with advanced progressive disease and no renal or hepatic comorbidity","genericName":"Morphine sulfate sustained-release","dose":"10 mg to 15 mg","route":"Oral","frequency":"Twice daily","duration":"Initial titration phase; adjust to response with frequent review","adjustments":["Seek specialist advice before prescribing in moderate to severe renal or hepatic impairment","Individualise after assessing prior opioid exposure and adverse effects"],"monitoring":["Pain control","Sedation and signs of opioid toxicity","Nausea and vomiting","Constipation"],"sourceTitle":"Palliative care for adults: strong opioids for pain relief","sourceUrl":"https://www.nice.org.uk/guidance/cg140/chapter/recommendations","sourceEdition":"CG140, published 23 May 2012; last updated 3 August 2016; Recommendations 1.1.1 to 1.1.10 and 1.1.17 to 1.1.20"},{"indication":"Rescue treatment for breakthrough pain during initial titration","patientGroup":"Opioid-naive adults with advanced progressive disease and no renal or hepatic comorbidity","genericName":"Morphine sulfate immediate-release","dose":"5 mg","route":"Oral","frequency":"As rescue doses for breakthrough pain during titration; exact maximum frequency requires local prescribing protocol","duration":"Initial titration phase","adjustments":["Seek specialist advice before prescribing in moderate to severe renal or hepatic impairment"],"monitoring":["Breakthrough-dose use","Pain control","Sedation and signs of opioid toxicity","Nausea and constipation"],"sourceTitle":"Palliative care for adults: strong opioids for pain relief","sourceUrl":"https://www.nice.org.uk/guidance/cg140/chapter/recommendations","sourceEdition":"CG140, published 23 May 2012; last updated 3 August 2016; Recommendations 1.1.1 to 1.1.10 and 1.1.17 to 1.1.20"}],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults with advanced and progressive disease who require strong opioids for pain, with the dosing extraction limited to opioid-naive patients without renal or hepatic comorbidity during initial titration. This older NICE guideline does not provide a complete contraindication or interaction set and must be checked against current controlled-drug rules, product information, renal and hepatic guidance, bowel regimens, Saudi formulary and local palliative-care protocols. The extracted starting doses do not apply to opioid-tolerant patients or those with moderate to severe renal or hepatic impairment. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"69e8a4c3-4d79-4a9a-a44b-0b9cf662235c","title":"Palliative care for adults: strong opioids for pain relief","issuer":"NICE","edition":"CG140, published 23 May 2012; last updated 3 August 2016","url":"https://www.nice.org.uk/guidance/cg140/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.1.10 and 1.1.17 to 1.1.20","primary_source":true}],"selection_rationale":"Unverified scope: Adults with advanced and progressive disease who require strong opioids for pain, with the dosing extraction limited to opioid-naive patients without renal or hepatic comorbidity during initial titration."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Structured pain, toxicity and organ-function assessment","clinical_question":"What are the pain pattern, prior opioid exposure, renal and hepatic status, side effects and patient concerns?","expected_finding":"The assessment identifies whether the source's oral morphine titration example applies and what specialist input is needed.","decision_rationale":"NICE limits the example starting dose to patients without renal or hepatic comorbidity and requires frequent review of pain control and side effects.","timeframe":"Before initiation and frequently during titration"},{"test":"Constipation and nausea review","clinical_question":"Are predictable opioid adverse effects developing and is preventive or therapeutic support adequate?","expected_finding":"Constipation is expected in nearly all patients; nausea may occur during initiation or dose change.","decision_rationale":"NICE includes explicit management recommendations for opioid-related constipation and nausea.","timeframe":"At initiation and every titration review"}],"evidence":{"sources":[{"id":"69e8a4c3-4d79-4a9a-a44b-0b9cf662235c","title":"Palliative care for adults: strong opioids for pain relief","issuer":"NICE","edition":"CG140, published 23 May 2012; last updated 3 August 2016","url":"https://www.nice.org.uk/guidance/cg140/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.1.10 and 1.1.17 to 1.1.20","primary_source":true}],"selection_rationale":"Unverified scope: Adults with advanced and progressive disease who require strong opioids for pain, with the dosing extraction limited to opioid-naive patients without renal or hepatic comorbidity during initial titration."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"For an opioid-naive adult without renal or hepatic comorbidity, NICE gives a typical oral morphine total daily starting dose of 20 mg to 30 mg, for example sustained-release morphine 10 mg to 15 mg twice daily, plus immediate-release morphine 5 mg orally as rescue during titration.","timeframe":"During initial titration with frequent review"},{"instruction":"Adjust until pain control and side effects are balanced; seek specialist advice after unsuccessful adjustments and before prescribing strong opioids in moderate to severe renal or hepatic impairment.","timeframe":"Throughout titration"},{"instruction":"Review gaps: This older NICE guideline does not provide a complete contraindication or interaction set and must be checked against current controlled-drug rules, product information, renal and hepatic guidance, bowel regimens, Saudi formulary and local palliative-care protocols. The extracted starting doses do not apply to opioid-tolerant patients or those with moderate to severe renal or hepatic impairment.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"69e8a4c3-4d79-4a9a-a44b-0b9cf662235c","title":"Palliative care for adults: strong opioids for pain relief","issuer":"NICE","edition":"CG140, published 23 May 2012; last updated 3 August 2016","url":"https://www.nice.org.uk/guidance/cg140/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.1.10 and 1.1.17 to 1.1.20","primary_source":true}],"selection_rationale":"Unverified scope: Adults with advanced and progressive disease who require strong opioids for pain, with the dosing extraction limited to opioid-naive patients without renal or hepatic comorbidity during initial titration."}}]},"nonClinicalManagement":{"patientEducation":["Explain cancer pain assessment and support in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Palliative Medicine / Oncology","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"3eaa3e4b-00e8-4bb1-b98a-c18526c67c8e","title":"Cardiovascular Risk Assessment","original_version_id":"3eaa3e4b-00e8-4bb1-b98a-c18526c67c8e","expected_hash":"514082facdc4ea9578ee578c3ddc6f42","source_url":"https://www.nice.org.uk/guidance/ng238/chapter/recommendations","source_title":"Cardiovascular disease: risk assessment and reduction, including lipid modification","issuer":"NICE","scope":"Adults without established cardiovascular disease being assessed for primary prevention, with selected lipid assessment, statin eligibility and monitoring recommendations.","content":{"id":"3eaa3e4b-00e8-4bb1-b98a-c18526c67c8e","title":"Cardiovascular Risk Assessment","specialty":"Family Medicine / Preventive Cardiology","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b003","lastReviewed":"2026-10-10","pillar":"Keep Well","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Atherosclerotic events arise from cumulative vascular exposure and thrombosis; risk-factor combinations alter absolute event probability. Preventive benefit should be judged against baseline risk, treatment burden, and patient preferences. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Atherosclerotic events arise from cumulative vascular exposure and thrombosis","risk-factor combinations alter absolute event probability. Preventive benefit should be judged against baseline risk, treatment burden, and patient preferences."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Cardiovascular Risk Assessment, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Chest pain, focal neurological symptoms or exertional syncope require diagnostic assessment","Severe hypertension with acute organ symptoms","Known vascular disease shifts to secondary prevention","Very high inherited lipid risk"]},"differentials":[{"condition":"Secondary prevention","distinguishingFeatures":"Prior cardiovascular event has a different risk and treatment framework."},{"condition":"Familial lipid disorder","distinguishingFeatures":"Marked LDL and family pattern warrant evaluation."},{"condition":"White-coat or masked hypertension","distinguishingFeatures":"Confirm with appropriate repeat or out-of-office measures."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Blood pressure confirmation, lipid profile, diabetes and kidney assessment; use locally validated risk method where available.","modalityTarget":"Blood pressure confirmation, lipid profile, diabetes and kidney assessment; use locally validated risk method where available. — Cardiovascular Risk Assessment","targetCondition":"Cardiovascular Risk Assessment","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Review smoking, family history, medicines, symptoms, and secondary causes as indicated.","modalityTarget":"Review smoking, family history, medicines, symptoms, and secondary causes as indicated. — Cause, complication, or risk relevant to Cardiovascular Risk Assessment","targetCondition":"Cause, complication, or risk relevant to Cardiovascular Risk Assessment","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Cardiovascular Risk Assessment","targetCondition":"Important alternative to Cardiovascular Risk Assessment","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults without established cardiovascular disease being assessed for primary prevention, with selected lipid assessment, statin eligibility and monitoring recommendations. QRISK3 is calibrated for a UK population and requires Saudi/local risk-model and formulary review. NICE names atorvastatin 20 mg but the cited recommendations do not provide a complete route, frequency, duration, interaction and contraindication set. Pregnancy is an explicit contraindication; product information and organ-function adjustments remain required. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"01df9a9d-f368-4cab-8d25-0882b989b283","title":"Cardiovascular disease: risk assessment and reduction, including lipid modification","issuer":"NICE","edition":"NG238, published 14 December 2023; recommendations retrieved 12 October 2026","url":"https://www.nice.org.uk/guidance/ng238/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.1.18, 1.4.1 to 1.6.9 and 1.11.1 to 1.11.7","primary_source":true}],"selection_rationale":"Unverified scope: Adults without established cardiovascular disease being assessed for primary prevention, with selected lipid assessment, statin eligibility and monitoring recommendations."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"QRISK3 10-year cardiovascular risk calculation","clinical_question":"What is the estimated 10-year CVD risk for an adult aged 25 to 84 without established CVD?","expected_finding":"A QRISK3 result supports shared prevention decisions; 10% or more is NICE's threshold for offering atorvastatin 20 mg in primary prevention.","decision_rationale":"NICE recommends QRISK3 in the specified population while recognising groups in whom risk may be underestimated or a tool should not be used.","timeframe":"At formal risk assessment and after meaningful risk-factor change"},{"test":"Full lipid profile and baseline statin safety assessment","clinical_question":"Are dyslipidaemia, secondary causes or baseline factors relevant to treatment present?","expected_finding":"Total cholesterol, HDL, non-HDL, LDL and triglycerides, plus diabetes status, renal function, transaminases and indicated TSH inform treatment and referral.","decision_rationale":"NICE specifies these measures before statin treatment and for specialist referral decisions.","timeframe":"Before starting lipid-lowering treatment"},{"test":"Lipid profile and liver transaminase monitoring","clinical_question":"Is treatment producing the intended lipid response without clinically important liver abnormality?","expected_finding":"Repeat results support adherence, response and safety review.","decision_rationale":"NICE recommends full lipid profile and transaminase testing 2 to 3 months after starting or changing treatment, with transaminase testing at 12 months.","timeframe":"2 to 3 months after starting or changing treatment; transaminases at 12 months"}],"evidence":{"sources":[{"id":"01df9a9d-f368-4cab-8d25-0882b989b283","title":"Cardiovascular disease: risk assessment and reduction, including lipid modification","issuer":"NICE","edition":"NG238, published 14 December 2023; recommendations retrieved 12 October 2026","url":"https://www.nice.org.uk/guidance/ng238/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.1.18, 1.4.1 to 1.6.9 and 1.11.1 to 1.11.7","primary_source":true}],"selection_rationale":"Unverified scope: Adults without established cardiovascular disease being assessed for primary prevention, with selected lipid assessment, statin eligibility and monitoring recommendations."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Discuss lifestyle change, personal preferences, comorbidity, polypharmacy, frailty and life expectancy before deciding on a statin; offer atorvastatin 20 mg when 10-year QRISK3 is 10% or more.","timeframe":"After formal assessment"},{"instruction":"Do not use statins in pregnancy; stop if pregnancy is possible, stop 3 months before attempting conception and do not restart until breastfeeding is finished.","timeframe":"Before and throughout statin treatment"},{"instruction":"Review gaps: QRISK3 is calibrated for a UK population and requires Saudi/local risk-model and formulary review. NICE names atorvastatin 20 mg but the cited recommendations do not provide a complete route, frequency, duration, interaction and contraindication set. Pregnancy is an explicit contraindication; product information and organ-function adjustments remain required.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"01df9a9d-f368-4cab-8d25-0882b989b283","title":"Cardiovascular disease: risk assessment and reduction, including lipid modification","issuer":"NICE","edition":"NG238, published 14 December 2023; recommendations retrieved 12 October 2026","url":"https://www.nice.org.uk/guidance/ng238/chapter/recommendations","locator":"Recommendations 1.1.1 to 1.1.18, 1.4.1 to 1.6.9 and 1.11.1 to 1.11.7","primary_source":true}],"selection_rationale":"Unverified scope: Adults without established cardiovascular disease being assessed for primary prevention, with selected lipid assessment, statin eligibility and monitoring recommendations."}}]},"nonClinicalManagement":{"patientEducation":["Explain cardiovascular risk assessment in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Family Medicine / Preventive Cardiology","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"eab57274-e256-4281-bd97-7ebe1fb49472","title":"Cataract Surgery Assessment and Preparation","original_version_id":"eab57274-e256-4281-bd97-7ebe1fb49472","expected_hash":"ec1aaf5e745a247cc6e268e843a8a785","source_url":"https://www.nice.org.uk/guidance/ng77/chapter/recommendations","source_title":"Cataracts in adults: management","issuer":"NICE","scope":"Adults aged 18 or older being considered and prepared for cataract surgery, including referral discussion, biometry and complication-risk assessment.","content":{"id":"eab57274-e256-4281-bd97-7ebe1fb49472","title":"Cataract Surgery Assessment and Preparation","specialty":"Ophthalmology","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b003","lastReviewed":"2026-10-10","pillar":"Planned Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Lens opacity scatters light and reduces visual function; surgery replaces the opaque lens with an intraocular implant. Benefit depends on cataract contribution, ocular comorbidity, refractive goals, and safe perioperative care. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Lens opacity scatters light and reduces visual function","surgery replaces the opaque lens with an intraocular implant. Benefit depends on cataract contribution, ocular comorbidity, refractive goals, and safe perioperative care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Cataract Surgery Assessment and Preparation, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Sudden visual loss or painful red eye is not routine cataract","Retinal disease or optic neuropathy may limit visual gain","Active ocular infection","Unclear capacity or unrealistic expectations requiring discussion"]},"differentials":[{"condition":"Refractive error","distinguishingFeatures":"Refraction may improve symptoms without surgery."},{"condition":"Macular degeneration or diabetic retinopathy","distinguishingFeatures":"May be the limiting cause of visual impairment."},{"condition":"Glaucoma","distinguishingFeatures":"May require separate or combined planning."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Visual acuity and ocular examination including lens, retina and optic nerve; biometry and consent per ophthalmology pathway.","modalityTarget":"Visual acuity and ocular examination including lens, retina and optic nerve; biometry and consent per ophthalmology pathway. — Cataract Surgery Assessment and Preparation","targetCondition":"Cataract Surgery Assessment and Preparation","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Review diabetes, anticoagulants, allergies, anaesthetic risk, transport and postoperative support.","modalityTarget":"Review diabetes, anticoagulants, allergies, anaesthetic risk, transport and postoperative support. — Cause, complication, or risk relevant to Cataract Surgery Assessment and Preparation","targetCondition":"Cause, complication, or risk relevant to Cataract Surgery Assessment and Preparation","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Cataract Surgery Assessment and Preparation","targetCondition":"Important alternative to Cataract Surgery Assessment and Preparation","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults aged 18 or older being considered and prepared for cataract surgery, including referral discussion, biometry and complication-risk assessment. The source does not provide a complete perioperative medicine, eye-drop, anaesthetic dose or contraindication set. Ophthalmology assessment, product information, anticoagulant handling, infection prevention and Saudi/local surgical protocols require reconciliation. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"7ec4f638-4dd6-41b1-b801-4d1a8ebf9592","title":"Cataracts in adults: management","issuer":"NICE","edition":"NG77, published 26 October 2017; surveillance reviewed 20 May 2025","url":"https://www.nice.org.uk/guidance/ng77/chapter/recommendations","locator":"Recommendations 1.2.1 to 1.3.13 and 1.7.1 to 1.9.3","primary_source":true}],"selection_rationale":"Unverified scope: Adults aged 18 or older being considered and prepared for cataract surgery, including referral discussion, biometry and complication-risk assessment."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Vision and quality-of-life assessment","clinical_question":"How does the cataract affect daily function, and does the person want surgery after discussing benefits and harms?","expected_finding":"The person's functional impact and preferences determine referral; visual acuity alone must not restrict access.","decision_rationale":"NICE bases referral on shared discussion of vision, quality of life, bilateral involvement and patient preference.","timeframe":"At referral assessment"},{"test":"Optical biometry with keratometry","clinical_question":"What axial length and corneal curvature should inform intraocular lens calculation?","expected_finding":"Optical biometry and keratometry provide the standard measurements; ultrasound is used when optical measurement is unavailable or inaccurate.","decision_rationale":"NICE recommends these measurements for people having cataract surgery.","timeframe":"During preoperative assessment"},{"test":"Validated surgical complication-risk stratification","clinical_question":"Is the person at increased risk during or after surgery?","expected_finding":"A validated risk result informs counselling, supervision and planning.","decision_rationale":"NICE recommends considering a validated algorithm and explaining the result to the patient.","timeframe":"Before surgery"}],"evidence":{"sources":[{"id":"7ec4f638-4dd6-41b1-b801-4d1a8ebf9592","title":"Cataracts in adults: management","issuer":"NICE","edition":"NG77, published 26 October 2017; surveillance reviewed 20 May 2025","url":"https://www.nice.org.uk/guidance/ng77/chapter/recommendations","locator":"Recommendations 1.2.1 to 1.3.13 and 1.7.1 to 1.9.3","primary_source":true}],"selection_rationale":"Unverified scope: Adults aged 18 or older being considered and prepared for cataract surgery, including referral discussion, biometry and complication-risk assessment."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Give tailored oral and written information on procedure, risks, benefits, alternatives, recovery, postoperative support and warning symptoms.","timeframe":"At referral, preoperative review and discharge"},{"instruction":"Do not restrict access to cataract surgery solely by visual-acuity threshold.","timeframe":"At referral decision"},{"instruction":"Review gaps: The source does not provide a complete perioperative medicine, eye-drop, anaesthetic dose or contraindication set. Ophthalmology assessment, product information, anticoagulant handling, infection prevention and Saudi/local surgical protocols require reconciliation.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"7ec4f638-4dd6-41b1-b801-4d1a8ebf9592","title":"Cataracts in adults: management","issuer":"NICE","edition":"NG77, published 26 October 2017; surveillance reviewed 20 May 2025","url":"https://www.nice.org.uk/guidance/ng77/chapter/recommendations","locator":"Recommendations 1.2.1 to 1.3.13 and 1.7.1 to 1.9.3","primary_source":true}],"selection_rationale":"Unverified scope: Adults aged 18 or older being considered and prepared for cataract surgery, including referral discussion, biometry and complication-risk assessment."}}]},"nonClinicalManagement":{"patientEducation":["Explain cataract surgery assessment and preparation in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Ophthalmology","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"3f47a009-d923-4a43-bce4-9357e38111e7","title":"Cervical Cancer Screening and Follow-Up","original_version_id":"3f47a009-d923-4a43-bce4-9357e38111e7","expected_hash":"9c4fac7f77edb0dfd6efb39fe3d38399","source_url":"https://www.gov.uk/government/publications/cervical-screening-programme-and-colposcopy-management/1-introduction-and-programme-policy","source_title":"NHS Cervical Screening Programme: introduction and programme policy","issuer":"Other","scope":"People with a cervix aged 24.5 to 64 in the English NHS screening programme; limited to primary HPV screening, routine interval and selected follow-up principles.","content":{"id":"3f47a009-d923-4a43-bce4-9357e38111e7","title":"Cervical Cancer Screening and Follow-Up","specialty":"Primary Care / Gynaecology","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b003","lastReviewed":"2026-10-10","pillar":"Keep Well","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Persistent oncogenic HPV infection can cause cervical epithelial change and invasive cancer. Vaccination and screening reduce risk, while age, prior history, test performance, and follow-up completion determine benefit. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Persistent oncogenic HPV infection can cause cervical epithelial change and invasive cancer. Vaccination and screening reduce risk, while age, prior history, test performance, and follow-up completion determine benefit.","Clinical expression and progression vary with baseline risk, comorbidity, treatment exposure, and access to timely care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Cervical Cancer Screening and Follow-Up, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Postcoital or unexplained bleeding requires diagnostic assessment","Visible cervical lesion or persistent discharge","Immunosuppression or prior high-grade disease","Pregnancy with a concerning symptom"]},"differentials":[{"condition":"Cervical cancer symptom evaluation","distinguishingFeatures":"Symptoms need diagnostic assessment, not screening alone."},{"condition":"Prior high-grade lesion","distinguishingFeatures":"Requires surveillance beyond routine screening."},{"condition":"Pregnancy-related bleeding","distinguishingFeatures":"Assess obstetric and cervical causes appropriately."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Review prior tests, pathology, treatment and national screening eligibility; perform examination/test only with consent.","modalityTarget":"Review prior tests, pathology, treatment and national screening eligibility; perform examination/test only with consent. — Cervical Cancer Screening and Follow-Up","targetCondition":"Cervical Cancer Screening and Follow-Up","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Use locally adopted HPV/cytology triage and track abnormal results to definitive review.","modalityTarget":"Use locally adopted HPV/cytology triage and track abnormal results to definitive review. — Cause, complication, or risk relevant to Cervical Cancer Screening and Follow-Up","targetCondition":"Cause, complication, or risk relevant to Cervical Cancer Screening and Follow-Up","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Cervical Cancer Screening and Follow-Up","targetCondition":"Important alternative to Cervical Cancer Screening and Follow-Up","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. People with a cervix aged 24.5 to 64 in the English NHS screening programme; limited to primary HPV screening, routine interval and selected follow-up principles. This English programme is not a Saudi screening schedule. Eligibility, age range, interval, sample method, laboratory workflow, referral thresholds and post-treatment follow-up must be reconciled with current Saudi policy. Symptoms require diagnostic assessment rather than routine screening. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"f470c677-a110-4081-8110-d53080732fc5","title":"NHS Cervical Screening Programme: introduction and programme policy","issuer":"Other","edition":"England programme guidance, updated 9 July 2025","url":"https://www.gov.uk/government/publications/cervical-screening-programme-and-colposcopy-management/1-introduction-and-programme-policy","locator":"Sections 1.1 to 1.3 and 2.1 to 2.2","primary_source":true}],"selection_rationale":"Unverified scope: People with a cervix aged 24.5 to 64 in the English NHS screening programme; limited to primary HPV screening, routine interval and selected follow-up principles."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Primary high-risk HPV cervical screening with cytology triage","clinical_question":"Is high-risk HPV present and, if so, does reflex cytology identify a referral pathway?","expected_finding":"A negative primary hrHPV result supports routine recall; a positive result triggers cytology triage and programme-defined surveillance or colposcopy.","decision_rationale":"The NHS programme uses primary hrHPV screening because of higher sensitivity, with cytology triage to preserve specificity.","timeframe":"At the programme-defined screening interval"},{"test":"Eligibility and prior-result review","clinical_question":"Does age, cervical status, previous hrHPV positivity or prior abnormality change routine recall?","expected_finding":"The English programme first invites at 24.5 years and uses a 5-year interval after a negative primary hrHPV result, with exceptions for recent positivity and non-routine follow-up.","decision_rationale":"Programme policy defines different recall based on age and previous results.","timeframe":"Before invitation, sampling and discharge from follow-up"}],"evidence":{"sources":[{"id":"f470c677-a110-4081-8110-d53080732fc5","title":"NHS Cervical Screening Programme: introduction and programme policy","issuer":"Other","edition":"England programme guidance, updated 9 July 2025","url":"https://www.gov.uk/government/publications/cervical-screening-programme-and-colposcopy-management/1-introduction-and-programme-policy","locator":"Sections 1.1 to 1.3 and 2.1 to 2.2","primary_source":true}],"selection_rationale":"Unverified scope: People with a cervix aged 24.5 to 64 in the English NHS screening programme; limited to primary HPV screening, routine interval and selected follow-up principles."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Use the current local programme pathway for sample processing, result communication, surveillance and colposcopy referral; do not apply an English interval without Saudi reconciliation.","timeframe":"At every screening episode"},{"instruction":"Assess cervical-cancer symptoms through a diagnostic pathway rather than waiting for or relying on a screening test.","timeframe":"Whenever symptoms are present"},{"instruction":"Review gaps: This English programme is not a Saudi screening schedule. Eligibility, age range, interval, sample method, laboratory workflow, referral thresholds and post-treatment follow-up must be reconciled with current Saudi policy. Symptoms require diagnostic assessment rather than routine screening.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"f470c677-a110-4081-8110-d53080732fc5","title":"NHS Cervical Screening Programme: introduction and programme policy","issuer":"Other","edition":"England programme guidance, updated 9 July 2025","url":"https://www.gov.uk/government/publications/cervical-screening-programme-and-colposcopy-management/1-introduction-and-programme-policy","locator":"Sections 1.1 to 1.3 and 2.1 to 2.2","primary_source":true}],"selection_rationale":"Unverified scope: People with a cervix aged 24.5 to 64 in the English NHS screening programme; limited to primary HPV screening, routine interval and selected follow-up principles."}}]},"nonClinicalManagement":{"patientEducation":["Explain cervical cancer screening and follow-up in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Primary Care / Gynaecology","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"81ec89af-5bc1-40e0-bf3b-52097c45af9f","title":"Childhood Immunisation and Catch-Up","original_version_id":"81ec89af-5bc1-40e0-bf3b-52097c45af9f","expected_hash":"09ab86185af7212d2edde153627c596d","source_url":"https://www.moh.gov.sa/en/healthawareness/educationalcontent/vaccination/pages/vaccination-2.aspx","source_title":"Saudi Ministry of Health: Children Vaccinations","issuer":"Other","scope":"Children attending routine immunisation or catch-up review in Saudi Arabia; limited to record review, timing, deferral and safety screening rather than a product-by-product schedule.","content":{"id":"81ec89af-5bc1-40e0-bf3b-52097c45af9f","title":"Childhood Immunisation and Catch-Up","specialty":"Paediatrics / Public Health","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b003","lastReviewed":"2026-10-10","pillar":"Keep Well","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Vaccination primes adaptive immune memory and reduces individual disease risk and transmission. Schedule timing, product, immune status, prior doses, and local epidemiology affect protection and catch-up planning. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Vaccination primes adaptive immune memory and reduces individual disease risk and transmission. Schedule timing, product, immune status, prior doses, and local epidemiology affect protection and catch-up planning.","Clinical expression and progression vary with baseline risk, comorbidity, treatment exposure, and access to timely care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Childhood Immunisation and Catch-Up, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Possible anaphylaxis after a prior dose","Severe acute illness requiring timing assessment","Immunocompromise or complex vaccine history","Exposure requiring time-sensitive prophylaxis"]},"differentials":[{"condition":"Incomplete documentation","distinguishingFeatures":"Use registry and prior-provider records; do not assume an undocumented dose was given."},{"condition":"True contraindication","distinguishingFeatures":"Distinguish severe allergy or live-vaccine restriction from minor illness or expected reaction."},{"condition":"Post-vaccine adverse event","distinguishingFeatures":"Assess timing and severity; report through local safety pathway."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Review official national registry, written record and prior products/dates; assess age, risk, immune status and allergy history.","modalityTarget":"Review official national registry, written record and prior products/dates; assess age, risk, immune status and allergy history. — Childhood Immunisation and Catch-Up","targetCondition":"Childhood Immunisation and Catch-Up","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Use current Saudi MOH/PH authority schedule for catch-up decisions; document product, batch, site and next due date.","modalityTarget":"Use current Saudi MOH/PH authority schedule for catch-up decisions; document product, batch, site and next due date. — Cause, complication, or risk relevant to Childhood Immunisation and Catch-Up","targetCondition":"Cause, complication, or risk relevant to Childhood Immunisation and Catch-Up","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading 