t":false,"content_hash":"73352fe27507b20906319aaa98dd56d3","guideline_id":"c36e9014-7d53-4a82-b641-8e05a3c9d627"},{"id":"fb440d70-f345-4ece-be8b-181f403de434","status":"published","version":"1.0-draft","is_current":true,"content_hash":"b57db46f5ba63ed0ed92840a5bc59bc8","guideline_id":"fb440d70-f345-4ece-be8b-181f403de434"},{"id":"fb9beeaa-3aba-4392-9de7-4b4ce44e2d03","status":"under_review","version":"investigations-2026-10-11-v1","is_current":false,"content_hash":"ed37a89f80ba647d758898ebfc4d0d2b","guideline_id":"06bb691f-eef3-4b1f-a0fc-29b94afd9254"},{"id":"fbcfdac2-c63e-4f8b-a5d8-bc141517c6af","status":"under_review","version":"emergency-2026-10-12-v1","is_current":false,"content_hash":"62876658f76976690399aec668db3330","guideline_id":"a1010000-0000-4000-8000-000000000002"}]$baseline$)
as x(id uuid,guideline_id uuid,version text,status text,is_current boolean,content_hash text);
do $guard$ begin
 if (select count(*) from population_batch) <> 10 then raise exception 'Strict batch size must be ten'; end if;
 if (select count(*) from clinical_guidelines where organization_id is null and is_shared_reference) <> 81 then raise exception 'Master catalogue changed; reconcile before applying'; end if;
 if exists(select 1 from population_baseline b left join guideline_versions v on v.id=b.id where v.id is null or v.guideline_id<>b.guideline_id or md5(v.content::text)<>b.content_hash or v.status::text<>b.status or v.is_current<>b.is_current) then raise exception 'Existing version changed; stopping without writes'; end if;
 if exists(select 1 from population_batch p left join guideline_versions v on v.id=p.original_version_id and v.guideline_id=p.id and v.is_current where v.id is null or md5(v.content::text)<>p.expected_hash) then raise exception 'Current version guard failed'; end if;
 if exists(select 1 from population_batch p join guideline_versions v on v.guideline_id=p.id and v.version='official-extraction-2026-10-11-b003' where v.content<>p.content or v.status<>'draft' or v.is_current or v.approved_by is not null or v.approved_at is not null or v.published_at is not null) then raise exception 'Conflicting batch already exists; never overwrite'; end if;
end $guard$;
insert into guideline_versions(guideline_id,version,version_number,status,content,change_summary,source_title,issuing_organization,source_url,jurisdiction,review_date,created_by,is_current)
select p.id,'official-extraction-2026-10-11-b003','official-extraction-2026-10-11-b003','draft',p.content,
 'Automated official-guideline extraction; unverified limited-scope draft. '||p.scope||' Existing source version: '||p.original_version_id::text||'. No clinician approval or new verification date recorded. Graph validation is structural only.',
 p.source_title,p.issuer,p.source_url,'International; Saudi adaptation pending',
 (select v.review_date from public.guideline_versions v where v.id=p.original_version_id),null,false
from population_batch p
on conflict(guideline_id,version) do nothing;
do $after$ begin
 if (select count(*) from guideline_versions v join population_batch p on p.id=v.guideline_id where v.version='official-extraction-2026-10-11-b003' and v.status='draft' and not v.is_current and v.approved_by is null and v.approved_at is null and v.published_at is null and v.last_verified_date is null and v.content->>'clinicalReviewStatus'='pending') <> 10 then raise exception 'Draft read-back invariant failed'; end if;
 if exists(select 1 from population_baseline b left join guideline_versions v on v.id=b.id where v.id is null or md5(v.content::text)<>b.content_hash or v.status::text<>b.status or v.is_current<>b.is_current) then raise exception 'Original history changed'; end if;
end $after$;
commit;
select id,guideline_id,version,status,is_current,approved_by,approved_at,published_at,last_verified_date,content->>'clinicalReviewStatus' review_status from guideline_versions where version='official-extraction-2026-10-11-b003' order by guideline_id;
